<script setup lang="ts">
import {onMounted,ref} from 'vue'; import {api,describe,session} from '../api'; import type {Project,Member,User} from '../types'
const projects=ref<Project[]>([]), roles=ref<Record<number,string>>({}), error=ref(''), busy=ref(true), name=ref(''), description=ref(''), creating=ref(false)
async function load(){busy.value=true;error.value='';try {if(!session.user) session.user=await api<User>('/api/users/me'); projects.value=await api<Project[]>('/api/projects'); const pairs=await Promise.all(projects.value.map(async p=>{try{const m=await api<Member[]>(`/api/projects/${p.id}/members`);return [p.id,m.find(x=>x.userId===session.user?.id)?.role || '未知'] as const}catch{return [p.id,'未知'] as const}}));roles.value=Object.fromEntries(pairs)}catch(e){error.value=describe(e)}finally{busy.value=false}}
async function create(){creating.value=true;try{await api<Project>('/api/projects',{method:'POST',body:JSON.stringify({name:name.value,description:description.value||null})});name.value='';description.value='';await load()}catch(e){error.value=describe(e)}finally{creating.value=false}}
onMounted(load)
</script>
<template><div class="page-head"><div><p class="eyebrow">WORKSPACE / 项目</p><h1>选择项目</h1><p class="muted">在项目中管理会议记录与行动任务。</p></div><span class="count">{{projects.length}} 个项目</span></div><p v-if="error" class="error">{{error}}</p><p v-if="busy" class="muted">正在加载项目…</p><div v-else class="project-grid"><router-link v-for="p in projects" :key="p.id" class="card project-card" :to="`/projects/${p.id}/import`"><div class="project-icon">{{p.name.slice(0,1)}}</div><div class="row"><h2>{{p.name}}</h2><span class="badge">{{roles[p.id] || '未知'}}</span></div><p class="muted">{{p.description || '暂无项目描述'}}</p><span class="card-action">进入工作台 →</span></router-link><div v-if="!projects.length" class="card muted">暂无项目，可在下方创建。</div></div><section class="card create"><h2>创建项目</h2><form class="create-form" @submit.prevent="create"><label>项目名称<input v-model.trim="name" maxlength="200" required></label><label>项目描述<input v-model.trim="description" maxlength="1000" placeholder="选填"></label><button class="primary" :disabled="creating">创建项目</button></form></section></template>
